// Prism Looks parity: DaedalusPrismLooksCore.h must reproduce every skin row, unlock list, pick and reject in
// prism_looks_parity.txt (generated by tools/minigames/prism_looks_parity.py).
//   g++ -std=c++17 -O1 -Wall -Wextra -Wshadow -Werror -I../DaedalusLink/Source/DaedalusLink/Public prism_looks_core_test.cpp -o prism_looks_core_test && ./prism_looks_core_test prism_looks_parity.txt
#include "DaedalusPrismLooksCore.h"
#include <cstdio>
#include <fstream>
#include <string>

using namespace daedalus::prism_looks;

namespace {

std::string Field(const std::string& Line, const std::string& Key)
{
	const std::string Needle = " " + Key + "=";
	const size_t P = Line.find(Needle);
	if (P == std::string::npos) return "";
	const size_t S = P + Needle.size(), E = Line.find(' ', S);
	return Line.substr(S, E == std::string::npos ? std::string::npos : E - S);
}

std::string Hex(uint32_t V)
{
	char B[8];
	std::snprintf(B, sizeof B, "%06X", static_cast<unsigned>(V));
	return B;
}

int Fails = 0;

void Expect(bool Ok, int LineNo, const std::string& What)
{
	if (!Ok && ++Fails <= 20) std::printf("line %d: %s\n", LineNo, What.c_str());
}

}  // namespace

int main(int Argc, char** Argv)
{
	if (Argc < 2)
	{
		std::printf("usage: prism_looks_core_test prism_looks_parity.txt\n");
		return 2;
	}
	std::ifstream In(Argv[1]);
	if (!In)
	{
		std::printf("cannot open %s\n", Argv[1]);
		return 2;
	}
	std::string Line;
	int No = 0, SkinRows = 0, Unlocks = 0, Picks = 0, Rejects = 0;
	while (std::getline(In, Line))
	{
		++No;
		if (Line.empty() || Line[0] == '#') continue;
		const std::string Kind = Line.substr(0, Line.find(' '));
		const std::string G = Field(Line, "g");
		if (Kind == "skin")
		{
			Expect(SkinRows < static_cast<int>(Skins.size()), No, "more skin rows than the table");
			if (SkinRows >= static_cast<int>(Skins.size())) continue;
			const Skin& S = Skins[SkinRows++];
			std::string Name = S.Name;
			for (char& C : Name)
				if (C == ' ') C = '+';
			Expect(G == S.Game && Field(Line, "id") == S.Id && Field(Line, "name") == Name, No, "skin id/name");
			Expect(Field(Line, "base") == Hex(S.Base) && Field(Line, "accent") == Hex(S.Accent) &&
				Field(Line, "glow") == Hex(S.Glow), No, "skin colours");
			Expect(Field(Line, "seal") == std::to_string(S.Seal), No, "skin seal");
			Expect(Field(Line, "gap") == std::to_string(LumaGap(S)) && LumaGap(S) >= MinLumaGap, No, "luma gap");
		}
		else if (Kind == "unlock")
		{
			++Unlocks;
			std::vector<std::string> Ids;
			const bool Ok = Unlocked(G, std::stoi(Field(Line, "seal")), Ids);
			std::string Joined;
			for (const std::string& Id : Ids) Joined += (Joined.empty() ? "" : ",") + Id;
			Expect(Ok && Joined == Field(Line, "skins"), No, "unlock list " + Joined);
		}
		else if (Kind == "pick")
		{
			++Picks;
			const std::string Want = Field(Line, "want");
			const std::string Got = Pick(G, std::stoi(Field(Line, "seal")), Want == "-" ? std::string() : Want);
			Expect(Got == Field(Line, "show"), No, "pick " + Got);
		}
		else if (Kind == "reject")
		{
			++Rejects;
			std::vector<std::string> Ids;
			Expect(!Unlocked(G == "-" ? std::string() : G, std::stoi(Field(Line, "seal")), Ids) &&
				Pick(G == "-" ? std::string() : G, std::stoi(Field(Line, "seal")), "").empty(), No, "should reject");
		}
		else
			Expect(false, No, "unknown line kind " + Kind);
	}
	Expect(SkinRows == static_cast<int>(Skins.size()), No, "skin row count");
	Expect(Unlocks == 77 && Picks == 275 && Rejects == 5, No, "line counts");
	std::printf("prism_looks: %d skins, %d unlocks, %d picks, %d rejects, %d failures\n", SkinRows, Unlocks, Picks, Rejects, Fails);
	return Fails == 0 ? 0 : 1;
}
